'use client'
/** Weather: the MATRIX card `weather`. Generated by scripts/registry/generate.ts. */
import { MatrixDotCard, type MatrixDotCardProps } from '@/components/matrix/dot-card'
import { henryBoard } from '@/lib/matrix/widgets/boards/henry'

const preset = henryBoard.find(p => p.id === 'weather')!

export type MatrixWeatherProps = Omit<MatrixDotCardProps, 'preset'>

export function MatrixWeather(props: MatrixWeatherProps) {
  return <MatrixDotCard preset={preset} {...props} />
}
